observation.command:
cd /workspace && cat > /tmp/serve.mjs <<'EOF'
import http from 'http';
import fs from 'fs';
import path from 'path';
const root='/workspace/build';
const types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.png':'image/png','.svg':'image/svg+xml','.ico':'image/x-icon'};
http.createServer((req,res)=>{
  let p=decodeURIComponent(req.url.split('?')[0]);
  let f=path.join(root,p);
  if(p.endsWith('/')) f=path.join(f,'index.html');
  if(!fs.existsSync(f)||fs.statSync(f).isDirectory()) f=path.join(f,'index.html');
  if(!fs.existsSync(f)){res.writeHead(404);res.end('nf');return;}
  res.writeHead(200,{'Content-Type':types[path.extname(f)]||'application/octet-stream'});
  fs.createReadStream(f).pipe(res);
}).listen(8099,'127.0.0.1',()=>console.log('up'));
EOF
node /tmp/serve.mjs & sleep 2
for u in / /de/ /en/ /de/resources/ /en/resources/joinup/ /fit-standards/; do printf "%s -> " "$u"; curl -s -o /dev/null -w "%{http_code}\n" "http://127.0.0.1:8099$u"; done
curl -s http://127.0.0.1:8099/de/ | grep -o '<title>[^<]*</title>'
kill %1 2>/dev/null
